// Zalo Mini App – Get Phone Number
// Docs: https://miniapp.zaloplatforms.com/documents/api/getPhoneNumber/
async getPhoneNumber() {
  const access_token = await getAccessToken();
  const code = await getPhoneNumber();
  const secret_key = "your zalo app secret key";

  const response = await fetch("https://graph.zalo.me/v2.0/me/info", {
    headers: {
      access_token,
      code: code.token!,
      secret_key,
    },
  });
  const data = await response.json();
  return data.data.number;
},

patches.replace:
// Zalo Mini App – Get Phone Number
// Docs: https://miniapp.zaloplatforms.com/documents/api/getPhoneNumber/
//
// DX compatibility adapter, pinned to upstream 8c692b9.
// Upstream performed the server-side decode INSIDE the client: it embedded an App Secret
// literal and called the Zalo Graph endpoint straight from the browser. Everything in client
// code ends up in the bundle, so that hands the secret to every user — it can never ship.
// The SDK only ever returns a short-lived TOKEN; exchanging that token for a number needs the
// App Secret and MUST happen on your own backend.
// Guide: create-zmp-app references/phone-number-backend.md
async getPhoneNumber(): Promise<
  { source: "simulator"; number: string } | { source: "backend-required" }
> {
  type DxRuntime = {
    schemaVersion?: number;
    mode?: string;
    mockData?: { phoneNumber?: string };
  };
  const dx = (window as unknown as { __ZMP_DX_RUNTIME__?: DxRuntime }).__ZMP_DX_RUNTIME__;
  // Fail closed. Only the explicit DX simulator marker unlocks mock data: the simulator
  // serves from the real Zalo hostname and path on purpose, so URL, host and user-agent
  // prove nothing about which environment this is.
  if (dx?.schemaVersion === 1 && dx.mode === "simulator" && dx.mockData?.phoneNumber) {
    return { source: "simulator", number: String(dx.mockData.phoneNumber) };
  }
  return { source: "backend-required" };
},

const { openSnackbar } = useSnackbar();
const [phoneSource, setPhoneSource] = useState<
  "unknown" | "simulator" | "backend-required"
>("unknown");

