patches.replace:
(async () => {
  const result = await userService.getPhoneNumber();
  if (result.source === "simulator") {
    form.setFieldValue("phone", result.number);
    setPhoneSource("simulator");
    return;
  }
  // Outside the simulator we never invent a number: the field stays empty and the UI says
  // what is missing. Upstream caught every error, showed a "success" snackbar and filled
  // a hardcoded fake number the user could submit without noticing.
  setPhoneSource("backend-required");
})();

  label={renderRequiredLabel("Số điện thoại")}
